"use client";
// @zeus-internal
import { Clock3, Video } from "lucide-react";
import { useCallback, useId, useRef, useState } from "react";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { BookingDialog } from "./01-booking/booking-dialog";
import { firstOpenDay, MonthCalendar, type MonthView } from "./01-booking/calendar";
import { type Booking, type ClockFormat, type Day, DURATIONS, type Duration, HOST, HOST_TIME_ZONE, MEETING, makeDay, slotsFor, TODAY, } from "./01-booking/data";
import { TimeSlots } from "./01-booking/time-slots";
const DURATION_TABS = DURATIONS.map((minutes) => ({ value: String(minutes), label: `${minutes} min` }));
export default function CalendarBooking() {
    const id = useId();
    const rootRef = useRef<HTMLDivElement>(null);
    const [duration, setDuration] = useState<Duration>(30);
    const [zone, setZone] = useState(HOST_TIME_ZONE);
    const [format, setFormat] = useState<ClockFormat>("12h");
    const [selectedDay, setSelectedDay] = useState<Day>(TODAY);
    const [view, setView] = useState<MonthView>({ y: TODAY.y, m: TODAY.m });
    const [direction, setDirection] = useState(1);
    const [focusDay, setFocusDay] = useState<Day>(TODAY);
    const [selectedSlot, setSelectedSlot] = useState<number | null>(null);
    const [pending, setPending] = useState<Booking | null>(null);
    const [dialogOpen, setDialogOpen] = useState(false);
    const [previous, setPrevious] = useState<Booking | null>(null);
    const openCount = useCallback((day: Day) => slotsFor(day, duration).length, [duration]);
    const slots = slotsFor(selectedDay, duration);
    const showMonth = (next: MonthView) => {
        const delta = next.y * 12 + next.m - (view.y * 12 + view.m);
        if (delta !== 0) {
            setDirection(delta > 0 ? 1 : -1);
            setView(next);
        }
    };
    return (<div ref={rootRef} className="art:w-full art:px-4 art:py-10 art:@min-[640px]/artemis:px-6">
      <div className="art:@container art:mx-auto art:w-full art:max-w-5xl">
      <div className="art:grid art:w-full art:overflow-clip art:rounded-3xl art:border art:border-border art:bg-background art:text-foreground art:@3xl:grid-cols-2 art:@5xl:grid-cols-[minmax(0,17rem)_minmax(0,1fr)_minmax(0,19rem)]">
        <div className="art:border-border art:border-b art:p-5 art:@min-[640px]/artemis:p-6 art:@3xl:col-span-2 art:@5xl:col-span-1 art:@5xl:border-r art:@5xl:border-b-0">
          <div className="art:flex art:flex-col art:gap-6">
            <div className="art:flex art:items-center art:gap-3">

              <img src={HOST.avatar} alt={HOST.name} width={48} height={48} className="art:size-12 art:shrink-0 art:rounded-full art:object-cover"/>
              <div className="art:min-w-0">
                <p className="art:truncate art:font-medium art:text-sm">{HOST.name}</p>
                <p className="art:truncate art:text-muted-foreground art:text-xs">
                  {HOST.role} · {HOST.company}
                </p>
              </div>
            </div>
            <div className="art:flex art:flex-col art:gap-2">
              <h2 className="art:text-balance art:font-medium art:text-xl">{MEETING.title}</h2>
              <p className="art:text-pretty art:text-muted-foreground art:text-sm">{MEETING.description}</p>
            </div>
            <div className="art:flex art:flex-col art:gap-2">
              <p className="art:flex art:items-center art:gap-2 art:font-medium art:text-muted-foreground art:text-xs">
                <Clock3 className="art:size-3.5"/>
                Meeting length
              </p>
              <div>
                <ArtemisSegmentedTabs items={DURATION_TABS} value={String(duration)} onValueChange={(value) => {
            setDuration(Number(value) as Duration);
            setSelectedSlot(null);
        }} ariaLabel="Meeting length" listClassName="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:w-full art:*:flex-1" buttonClassName="art:rounded-full art:w-full art:tabular-nums"/>
              </div>
            </div>
            <div className="art:flex art:items-start art:gap-3">
              <span className="art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground">
                <Video className="art:size-4"/>
              </span>
              <div className="art:min-w-0">
                <p className="art:font-medium art:text-sm">{MEETING.location}</p>
                <p className="art:text-muted-foreground art:text-xs">{MEETING.locationNote}</p>
              </div>
            </div>
          </div>
        </div>
        <div className="art:border-border art:border-b art:p-5 art:@min-[640px]/artemis:p-6 art:@3xl:border-r art:@3xl:border-b-0">
          <MonthCalendar headingId={`${id}-month`} view={view} direction={direction} selected={selectedDay} focusDay={focusDay} layoutId={`${id}-selected-day`} openCount={openCount} onSelect={(day) => {
            setSelectedDay(day);
            setFocusDay(day);
            setSelectedSlot(null);
        }} onMonthStep={(step) => {
            const next = makeDay(view.y, view.m + step, 1);
            const month = { y: next.y, m: next.m };
            showMonth(month);
            setFocusDay(firstOpenDay(month, openCount));
        }} onFocusDay={(day) => {
            showMonth({ y: day.y, m: day.m });
            setFocusDay(day);
        }}/>
        </div>
        <div className="art:p-5 art:@min-[640px]/artemis:p-6">
          <TimeSlots day={selectedDay} duration={duration} slots={slots} zone={zone} format={format} selectedSlot={selectedSlot} previous={previous} onZoneChange={setZone} onFormatChange={setFormat} onSelectSlot={setSelectedSlot} onConfirm={() => {
            if (selectedSlot === null)
                return;
            setPending({ day: selectedDay, start: selectedSlot, duration, zone, format });
            setDialogOpen(true);
        }}/>
        </div>
      </div>
      </div>
      <BookingDialog open={dialogOpen} booking={pending} onBooked={() => setSelectedSlot(null)} onCancel={() => setDialogOpen(false)} onDone={() => {
            setDialogOpen(false);
            setSelectedSlot(null);
        }} onReschedule={() => {
            const slot = rootRef.current?.querySelectorAll<HTMLButtonElement>("ul[aria-label] li > button")[pending ? slots.indexOf(pending.start) : -1];
            setDialogOpen(false);
            setSelectedSlot(null);
            setPrevious(pending);
            window.setTimeout(() => slot?.focus(), 320);
        }}/>
    </div>);
}

"use client";
