function LinkButton({ className, ...props }: Omit<HTMLMotionProps<"a">, "className"> & {
    className?: string;
}) {
    const reduce = useReducedMotion();
    return (<motion.a className={artemisButtonClasses({ variant: "tertiary", size: "md", className })} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} tabIndex={0} {...props}/>);
}
const VIEW_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const VIEW_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 10 };
const VIEW_TRANSITION = { duration: 0.36, ease: ARTEMIS_EASE_OUT };
const VIEW_EXIT = { opacity: 0, filter: "blur(4px)", transition: { duration: 0.15, ease: [0.4, 0, 1, 1] } } as const;
function BookingForm({ booking, phase, onSubmit, onCancel, }: {
    booking: Booking;
    phase: Phase;
    onSubmit: () => void;
