}) {
    const reduce = useReducedMotion();
    const id = useId();
    const [name, setName] = useState("");
    const [email, setEmail] = useState("");
    const [notes, setNotes] = useState("");
    const [guest, setGuest] = useState("");
    const [guests, setGuests] = useState<string[]>([]);
    const [guestError, setGuestError] = useState(false);
    const [invalidName, setInvalidName] = useState(false);
    const [invalidEmail, setInvalidEmail] = useState(false);
    const busy = phase !== "idle";
    const nameError = invalidName ? "Add your name." : undefined;
    const emailError = invalidEmail ? "Enter a valid email." : undefined;
    const addGuest = () => {
        const value = guest.trim();
        if (!value)
            return;
        if (!EMAIL_PATTERN.test(value)) {
            setGuestError(true);
            return;
        }
        setGuests((prev) => (prev.includes(value) ? prev : [...prev, value]));
        setGuest("");
        setGuestError(false);
    };
    const submit = (event: FormEvent) => {
        event.preventDefault();
        if (busy)
            return;
        setInvalidName(!name.trim());
        setInvalidEmail(!EMAIL_PATTERN.test(email.trim()));
        if (!name.trim() || !EMAIL_PATTERN.test(email.trim()))
            return;
        onSubmit();
