            <motion.path d="M15 24.5l6 6L33 18" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" initial={{ pathLength: reduce ? 1 : 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT, delay: 0.25 }}/>
