    const close = () => succeeded.current ? onDone() : onCancel();
    return (<BookingModal open={open && booking !== null} onClose={close} panelClassName="art:max-w-lg art:rounded-2xl">
      {booking ? <DialogBody booking={booking} onCancel={close} onDone={onDone} onReschedule={onReschedule} onSuccess={() => { succeeded.current = true; onBooked(); }}/> : null}
