    const reduce = useReducedMotion();
    const [phase, setPhase] = useState<Phase>("idle");
    const [view, setView] = useState<"form" | "success">("form");
    const timers = useRef<number[]>([]);
    useEffect(() => () => {
        for (const t of timers.current)
            window.clearTimeout(t);
