    const submit = () => {
        setPhase("busy");
        timers.current.push(window.setTimeout(() => {
            setPhase("done");
            timers.current.push(window.setTimeout(() => { onSuccess(); setView("success"); }, reduce ? 0 : 650));
        }, 1100));
    };
    return (<div className="art:p-5 art:@min-[640px]/artemis:p-6">
      <AnimatePresence mode="wait" initial={false}>
        {view === "form" ? (<BookingForm key="form" booking={booking} phase={phase} onSubmit={submit} onCancel={onCancel}/>) : (<BookingSuccess key="success" booking={booking} onReschedule={onReschedule} onDone={onDone}/>)}
      </AnimatePresence>
    </div>);
}

