    onSelect: (day: Day) => void;
    onMonthStep: (step: number) => void;
    onFocusDay: (day: Day) => void;
}) {
    const reduce = useReducedMotion();
    const buttons = useRef(new Map<string, HTMLButtonElement>());
    const pendingFocus = useRef<string | null>(null);
    useEffect(() => {
        const key = pendingFocus.current;
        if (!key)
            return;
        const button = buttons.current.get(key);
        if (button) {
            pendingFocus.current = null;
            button.focus();
        }
    });
    const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, day: Day) => {
        let target: Day | null = null;
        const weekday = weekdayIndex(day);
        switch (event.key) {
            case "ArrowLeft":
                target = addDays(day, -1);
                break;
            case "ArrowRight":
                target = addDays(day, 1);
                break;
            case "ArrowUp":
                target = addDays(day, -7);
                break;
            case "ArrowDown":
                target = addDays(day, 7);
                break;
            case "Home":
                target = addDays(day, -weekday);
                break;
            case "End":
                target = addDays(day, 6 - weekday);
                break;
            case "PageUp":
            case "PageDown": {
                const step = event.key === "PageUp" ? -1 : 1;
                const month = makeDay(day.y, day.m + step, 1);
                target = { y: month.y, m: month.m, d: Math.min(day.d, daysInMonth(month.y, month.m)) };
                break;
            }
            default:
                return;
        }
        event.preventDefault();
        if (compareDays(target, FIRST_DAY) < 0 || compareDays(target, LAST_DAY) > 0)
            return;
        pendingFocus.current = dayKey(target);
        onFocusDay(target);
    };
    const viewIndex = monthIndex(view);
    const leading = weekdayIndex({ y: view.y, m: view.m, d: 1 });
    const total = daysInMonth(view.y, view.m);
    const rows = Array.from({ length: 6 }, (_, row) => Array.from({ length: 7 }, (_, col) => {
        const d = row * 7 + col - leading + 1;
        return d >= 1 && d <= total ? d : null;
    }));
    return (<div className="art:flex art:flex-col art:gap-4">
      <div className="art:flex art:items-center art:justify-between art:gap-2">
        <h3 id={headingId} aria-live="polite" className="art:font-medium art:text-sm">
          {`${MONTHS[view.m]} ${view.y}`}
        </h3>
        <div className="art:flex art:items-center art:gap-1">
          <ArtemisButton variant="ghost" size="icon" className="art:size-9" aria-label="Previous month" disabled={viewIndex <= monthIndex(FIRST_MONTH)} onClick={() => onMonthStep(-1)}>
            <ChevronLeft className="art:size-4"/>
          </ArtemisButton>
          <ArtemisButton variant="ghost" size="icon" className="art:size-9" aria-label="Next month" disabled={viewIndex >= monthIndex(LAST_MONTH)} onClick={() => onMonthStep(1)}>
            <ChevronRight className="art:size-4"/>
          </ArtemisButton>
        </div>
      </div>
      <div className="art:flex art:flex-col art:gap-1">
        <div aria-hidden="true" className="art:grid art:grid-cols-7">
          {WEEKDAY_SHORT.map((label) => (<span key={label} className="art:py-1 art:text-center art:font-mono art:text-muted-foreground art:text-xs">
              {label}
            </span>))}
        </div>
        <div className="art:relative art:overflow-hidden">
          <AnimatePresence mode="popLayout" initial={false} custom={direction}>
            <motion.div key={viewIndex} custom={direction} variants={reduce ? REDUCED_MONTH_VARIANTS : MONTH_VARIANTS} initial="enter" animate="center" exit="exit">
              <table aria-labelledby={headingId} className="art:w-full art:table-fixed art:border-collapse">
                <thead className="art:sr-only">
                  <tr>
                    {WEEKDAYS.map((weekday) => (<th key={weekday} scope="col">
                        {weekday}
                      </th>))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((cells, row) => (<tr key={row}>
                      {cells.map((d, col) => {
                if (d === null) {
                    return <td key={col} className="art:h-11 art:@min-[640px]/artemis:h-12"/>;
                }
                const day: Day = { y: view.y, m: view.m, d };
                const open = openCount(day);
                const isSelected = open > 0 && sameDay(day, selected);
                const isToday = sameDay(day, TODAY);
                const key = dayKey(day);
                return (<td key={col} className="art:p-0.5 art:text-center">
                            <button type="button" ref={(node) => {
                        if (node)
                            buttons.current.set(key, node);
                        else
                            buttons.current.delete(key);
                    }} className={isSelected ? DAY_CLASS.selected : open > 0 ? DAY_CLASS.open : DAY_CLASS.unavailable} tabIndex={sameDay(day, focusDay) ? 0 : -1} aria-disabled={open > 0 ? undefined : true} aria-pressed={isSelected} aria-current={isToday ? "date" : undefined} aria-label={`${longDate(day)}, ${open > 0 ? `${open} open times` : "unavailable"}`} onClick={() => {
                        if (open > 0)
                            onSelect(day);
                    }} onFocus={() => onFocusDay(day)} onKeyDown={(event) => onKeyDown(event, day)}>
                              {isSelected ? (<motion.span layoutId={layoutId} className="art:absolute art:inset-0 art:-z-10 art:bg-primary" style={{ borderRadius: 9999 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}/>) : isToday ? (<span aria-hidden="true" className="art:absolute art:inset-0 art:-z-10 art:rounded-full art:border art:border-foreground/25"/>) : null}
                              <span className="art:leading-none">{d}</span>
                              <span aria-hidden="true" className="art:mt-1 art:flex art:h-1 art:items-center art:gap-0.5">
                                {open > 0
                        ? Array.from({ length: dotCount(open) }, (_, i) => (<span key={i} className={artemisCx("art:size-1 art:rounded-full art:transition-colors", isSelected ? "art:bg-primary-foreground/80" : "art:bg-primary/70")}/>))
                        : null}
                              </span>
                            </button>
                          </td>);
            })}
                    </tr>))}
                </tbody>
              </table>
            </motion.div>
          </AnimatePresence>
        </div>
      </div>
    </div>);
}

