export const pad2 = (n: number) => String(n).padStart(2, "0");
export const dayKey = (day: Day) => `${day.y}-${pad2(day.m + 1)}-${pad2(day.d)}`;
export const sameDay = (a: Day, b: Day) => a.y === b.y && a.m === b.m && a.d === b.d;
export const compareDays = (a: Day, b: Day) => (a.y - b.y) * 10000 + (a.m - b.m) * 100 + (a.d - b.d);
export function makeDay(y: number, m: number, d: number): Day {
    const date = new Date(Date.UTC(y, m, d));
    return { y: date.getUTCFullYear(), m: date.getUTCMonth(), d: date.getUTCDate() };
}
export const addDays = (day: Day, n: number) => makeDay(day.y, day.m, day.d + n);
export const daysInMonth = (y: number, m: number) => new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
export const weekdayIndex = (day: Day) => (new Date(Date.UTC(day.y, day.m, day.d)).getUTCDay() + 6) % 7;
export const MONTHS = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
