] as const;
export const WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"] as const;
export const WEEKDAY_SHORT = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"] as const;
export const longDate = (day: Day) => `${WEEKDAYS[weekdayIndex(day)]}, ${MONTHS[day.m]} ${day.d}`;
export function slotsFor(day: Day, duration: Duration): number[] {
    if (compareDays(day, TODAY) < 0 || compareDays(day, LAST_BOOKABLE) > 0)
        return [];
    const open = OPEN[dayKey(day)];
    if (!open)
        return [];
    const step = duration === 15 ? 15 : 30;
    const mask = duration === 15 ? open[1] : open[0];
    const out: number[] = [];
    for (let start = DAY_START, bit = 0; start < DAY_END; start += step, bit++) {
        if ((mask >>> bit) & 1 && start + duration <= DAY_END)
            out.push(start);
    }
    return out;
}
export const dotCount = (open: number) => (open >= 10 ? 3 : open >= 5 ? 2 : 1);
export const zoneById = (id: string) => TIME_ZONES.find((zone) => zone.id === id) ?? TIME_ZONES[1];
export function toZone(minutes: number, zone: TimeZoneOption) {
    const local = minutes + zone.offset - HOST_OFFSET;
    const shift = Math.floor(local / 1440);
    return { minutes: local - shift * 1440, shift };
}
export function formatClock(minutes: number, format: ClockFormat): string {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    if (format === "24h")
        return `${pad2(h)}:${pad2(m)}`;
    const suffix = h < 12 ? "AM" : "PM";
    return `${h % 12 === 0 ? 12 : h % 12}:${pad2(m)} ${suffix}`;
}
export function utcStamp(day: Day, minutes: number) {
    const date = new Date(Date.UTC(day.y, day.m, day.d, 0, minutes - HOST_OFFSET));
    const compact = `${date.getUTCFullYear()}${pad2(date.getUTCMonth() + 1)}${pad2(date.getUTCDate())}T${pad2(date.getUTCHours())}${pad2(date.getUTCMinutes())}00Z`;
    return { compact, iso: date.toISOString() };
}
export type Booking = {
    day: Day;
    start: number;
    duration: Duration;
    zone: string;
    format: ClockFormat;
};
export function calendarLinks(booking: Booking) {
    const start = utcStamp(booking.day, booking.start);
    const end = utcStamp(booking.day, booking.start + booking.duration);
    const title = `${MEETING.title} with ${HOST.name}`;
    const details = `${MEETING.description}

${HOST.company} \u00B7 ${HOST.role}`;
    const location = `${MEETING.location} \u00B7 ${MEETING.locationNote}`;
    const escape = (value: string) => value.replace(/\\/g, "\\\\").replace(/,/g, "\\,").replace(/;/g, "\\;").replace(/\n/g, "\\n");
    const ics = [
        "BEGIN:VCALENDAR",
        "VERSION:2.0",
        "PRODID:-//Artemis//Appointment booking//EN",
        "BEGIN:VEVENT",
        `UID:${start.compact}-${booking.duration}@booking`,
        `DTSTAMP:${start.compact}`,
        `DTSTART:${start.compact}`,
        `DTEND:${end.compact}`,
        `SUMMARY:${escape(title)}`,
        `DESCRIPTION:${escape(details)}`,
        `LOCATION:${escape(location)}`,
        "END:VEVENT",
        "END:VCALENDAR",
    ].join("\r\n");
    return { ics: `data:text/calendar;charset=utf-8,${encodeURIComponent(ics)}` };
}
export function bookingSummary(booking: Booking) {
    const zone = zoneById(booking.zone);
    const from = toZone(booking.start, zone);
    const to = toZone(booking.start + booking.duration, zone);
    return {
        date: longDate(addDays(booking.day, from.shift)),
        time: `${formatClock(from.minutes, booking.format)} \u2013 ${formatClock(to.minutes, booking.format)}`,
        duration: booking.duration,
        zone: zone.label,
    };
}
